import{_ as i,o as a,c as n,a0 as r}from"./chunks/framework.Cp0xpwNH.js";const h=JSON.parse('{"title":"Curriculum Principles","description":"","frontmatter":{},"headers":[],"relativePath":"CURRICULUM_PRINCIPLES.md","filePath":"CURRICULUM_PRINCIPLES.md"}'),t={name:"CURRICULUM_PRINCIPLES.md"};function o(s,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="curriculum-principles" tabindex="-1">Curriculum Principles <a class="header-anchor" href="#curriculum-principles" aria-label="Permalink to &quot;Curriculum Principles&quot;">​</a></h1><p><strong>Status:</strong> Living Document <strong>Precedence:</strong> Highest. If any other document in this project conflicts with this one, this document wins.</p><hr><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document defines the educational principles governing the Dutch B1 Curriculum project.</p><p>Every lesson, grammar explanation, vocabulary list, exercise, review, assessment, and AI-generated contribution must comply with these principles.</p><p>If you only read one document before contributing to this project, read this one.</p><hr><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><p>Create the highest-quality AI-assisted Dutch curriculum available for self-study learners, guiding complete beginners (A0) to an independent B1 level while emphasizing understanding, confidence, and long-term retention.</p><p>The curriculum must be:</p><ul><li>Progressive</li><li>Consistent</li><li>Accurate</li><li>Maintainable</li><li>AI-friendly</li><li>Human-friendly</li><li>Exam-ready</li></ul><hr><h2 id="educational-philosophy" tabindex="-1">Educational Philosophy <a class="header-anchor" href="#educational-philosophy" aria-label="Permalink to &quot;Educational Philosophy&quot;">​</a></h2><p>Language is a system. Students should understand the system rather than memorize isolated rules.</p><p>Every lesson should answer four questions: <strong>What? Why? How? When?</strong></p><p>Grammar is always explained through reasoning. Vocabulary always appears in meaningful context. Learning should feel cumulative rather than repetitive.</p><p><strong>See:</strong> <code>docs/TEACHING_PHILOSOPHY.md</code> for the full pedagogical rationale, worked examples, and per-level learning goals.</p><hr><h2 id="learning-principles" tabindex="-1">Learning Principles <a class="header-anchor" href="#learning-principles" aria-label="Permalink to &quot;Learning Principles&quot;">​</a></h2><h3 id="principle-1-build-before-expand" tabindex="-1">Principle 1 -- Build Before Expand <a class="header-anchor" href="#principle-1-build-before-expand" aria-label="Permalink to &quot;Principle 1 -- Build Before Expand&quot;">​</a></h3><p>Students first build a strong foundation. Only then should complexity increase.</p><h3 id="principle-2-one-major-concept" tabindex="-1">Principle 2 -- One Major Concept <a class="header-anchor" href="#principle-2-one-major-concept" aria-label="Permalink to &quot;Principle 2 -- One Major Concept&quot;">​</a></h3><p>Each lesson introduces one major grammar concept. Additional material reinforces previous concepts rather than competing for attention.</p><h3 id="principle-3-explain-before-memorize" tabindex="-1">Principle 3 -- Explain Before Memorize <a class="header-anchor" href="#principle-3-explain-before-memorize" aria-label="Permalink to &quot;Principle 3 -- Explain Before Memorize&quot;">​</a></h3><p>Grammar is explained before practice. Students understand patterns before attempting repetition.</p><h3 id="principle-4-learn-through-context" tabindex="-1">Principle 4 -- Learn Through Context <a class="header-anchor" href="#principle-4-learn-through-context" aria-label="Permalink to &quot;Principle 4 -- Learn Through Context&quot;">​</a></h3><p>Vocabulary is never presented as isolated word lists. Every word appears in example sentences, dialogues, reading, speaking, and writing.</p><h3 id="principle-5-active-production" tabindex="-1">Principle 5 -- Active Production <a class="header-anchor" href="#principle-5-active-production" aria-label="Permalink to &quot;Principle 5 -- Active Production&quot;">​</a></h3><p>Every lesson requires the learner to produce Dutch: speaking, writing, translation, or sentence creation. Passive recognition alone is insufficient.</p><h3 id="principle-6-continuous-review" tabindex="-1">Principle 6 -- Continuous Review <a class="header-anchor" href="#principle-6-continuous-review" aria-label="Permalink to &quot;Principle 6 -- Continuous Review&quot;">​</a></h3><p>Knowledge decays. Every lesson reinforces previous learning. Review lessons introduce no new material.</p><h3 id="principle-7-authentic-dutch" tabindex="-1">Principle 7 -- Authentic Dutch <a class="header-anchor" href="#principle-7-authentic-dutch" aria-label="Permalink to &quot;Principle 7 -- Authentic Dutch&quot;">​</a></h3><p>Whenever possible, use authentic Dutch. Avoid artificial textbook conversations. Natural language is preferred over perfectly simplified language, provided it remains appropriate for the learner&#39;s level.</p><h3 id="principle-8-english-as-a-bridge" tabindex="-1">Principle 8 -- English as a Bridge <a class="header-anchor" href="#principle-8-english-as-a-bridge" aria-label="Permalink to &quot;Principle 8 -- English as a Bridge&quot;">​</a></h3><p>The learner&#39;s native language is English. Grammar explanations compare Dutch with English whenever helpful. Do not assume knowledge of linguistic terminology.</p><h3 id="principle-9-communication-first" tabindex="-1">Principle 9 -- Communication First <a class="header-anchor" href="#principle-9-communication-first" aria-label="Permalink to &quot;Principle 9 -- Communication First&quot;">​</a></h3><p>The goal is communication. Grammar exists to improve communication, not to become an end in itself.</p><h3 id="principle-10-exam-readiness" tabindex="-1">Principle 10 -- Exam Readiness <a class="header-anchor" href="#principle-10-exam-readiness" aria-label="Permalink to &quot;Principle 10 -- Exam Readiness&quot;">​</a></h3><p>Every lesson contributes toward passing a Dutch B1 examination. Exam preparation begins from A0 rather than being postponed until B1.</p><hr><h2 id="curriculum-structure" tabindex="-1">Curriculum Structure <a class="header-anchor" href="#curriculum-structure" aria-label="Permalink to &quot;Curriculum Structure&quot;">​</a></h2><p>The curriculum consists of four CEFR levels: <strong>A0 (Foundations), A1 (Beginner), A2 (Elementary), B1 (Independent User)</strong>. Each level prepares the learner for the next.</p><p><strong>See:</strong> <code>docs/CEFR_GUIDE.md</code> for the detailed scope of each level (exit profile, grammar scope, vocabulary scope, communication, reading, listening, speaking, writing).</p><h3 id="curriculum-is-competency-driven-not-lesson-count-driven" tabindex="-1">Curriculum is competency-driven, not lesson-count-driven <a class="header-anchor" href="#curriculum-is-competency-driven-not-lesson-count-driven" aria-label="Permalink to &quot;Curriculum is competency-driven, not lesson-count-driven&quot;">​</a></h3><p>The curriculum is not designed by deciding how many lessons a level should have. It is designed by deciding what a learner must be able to do to leave that level. The number of lessons is a byproduct of that scope, never the starting point.</p><p>The content hierarchy is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CEFR Level</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Competency</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Unit</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Lesson</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Exercises</span></span></code></pre></div><ul><li>A <strong>Competency</strong> is a real-world ability the learner must gain (for example: &quot;Introducing Yourself,&quot; &quot;Shopping,&quot; &quot;Understanding Dutch Sounds&quot;). Every competency defines why it exists, what grammar it requires, what vocabulary it requires, what pronunciation it requires, what communication skills it requires, what cultural knowledge it requires, and how mastery is assessed.</li><li>A <strong>Unit</strong> groups the lessons that build one competency (for example, the &quot;Basic Sentences&quot; competency may contain the &quot;Personal Pronouns,&quot; &quot;Present Tense,&quot; and &quot;Word Order&quot; units).</li><li>A <strong>Lesson</strong> is the smallest instructional unit and always follows <code>docs/LESSON_STANDARD.md</code>.</li></ul><p><strong>See:</strong> <code>docs/COMPETENCY_MAP.md</code> for the authoritative list of competencies per level and the format each competency must follow.</p><p>Each level also contains Unit Reviews, a Mid-Level Review, a Final Review, and a Level Assessment. No review introduces new content. <strong>See:</strong> <code>docs/REVIEW_STRATEGY.md</code>.</p><hr><h2 id="lesson-structure" tabindex="-1">Lesson Structure <a class="header-anchor" href="#lesson-structure" aria-label="Permalink to &quot;Lesson Structure&quot;">​</a></h2><p>Every lesson follows the Lesson Standard&#39;s mandatory 20 sections, in order, none omitted.</p><p><strong>See:</strong> <code>docs/LESSON_STANDARD.md</code> for the full template.</p><hr><h2 id="grammar-principles" tabindex="-1">Grammar Principles <a class="header-anchor" href="#grammar-principles" aria-label="Permalink to &quot;Grammar Principles&quot;">​</a></h2><p>Grammar progresses from simple to complex. No grammar concept may appear before it has been introduced. Every explanation must include an explanation, reasoning, examples, comparison with English, common mistakes, and memory tips.</p><p>Grammar explanations live only in <code>shared/grammar/</code>. Lessons reference those files; they never duplicate them.</p><p><strong>See:</strong> <code>docs/GRAMMAR_STANDARD.md</code> (explanation format) and <code>docs/GRAMMAR_MAP.md</code> (progression and dependencies).</p><hr><h2 id="vocabulary-principles" tabindex="-1">Vocabulary Principles <a class="header-anchor" href="#vocabulary-principles" aria-label="Permalink to &quot;Vocabulary Principles&quot;">​</a></h2><p>Vocabulary is introduced according to frequency and usefulness, in this priority order:</p><ol><li>High-frequency words</li><li>Everyday communication</li><li>Exam usefulness</li><li>Cultural importance</li></ol><p>Every noun is stored together with its article (<code>de tafel</code>, <code>het huis</code>). Never teach nouns without articles. Every vocabulary item must exist in the master database before it is used in a lesson.</p><p><strong>See:</strong> <code>docs/VOCABULARY_STANDARD.md</code> (entry format) and <code>docs/VOCABULARY_ROADMAP.md</code> (progression and topic targets).</p><hr><h2 id="reading-principles" tabindex="-1">Reading Principles <a class="header-anchor" href="#reading-principles" aria-label="Permalink to &quot;Reading Principles&quot;">​</a></h2><p>Reading passages must use only known grammar, introduce minimal unknown vocabulary, feel natural, and reinforce lesson objectives. Reading length increases gradually across the curriculum.</p><h2 id="listening-principles" tabindex="-1">Listening Principles <a class="header-anchor" href="#listening-principles" aria-label="Permalink to &quot;Listening Principles&quot;">​</a></h2><p>Listening uses natural speech. Speech speed increases gradually. Different voices are introduced over time.</p><h2 id="speaking-principles" tabindex="-1">Speaking Principles <a class="header-anchor" href="#speaking-principles" aria-label="Permalink to &quot;Speaking Principles&quot;">​</a></h2><p>Speaking tasks simulate realistic situations. Avoid scripted conversations whenever possible. Encourage learners to create original sentences.</p><h2 id="writing-principles" tabindex="-1">Writing Principles <a class="header-anchor" href="#writing-principles" aria-label="Permalink to &quot;Writing Principles&quot;">​</a></h2><p>Writing begins on Day One. Difficulty increases gradually. Learners produce meaningful communication rather than isolated grammar drills.</p><h2 id="pronunciation-principles" tabindex="-1">Pronunciation Principles <a class="header-anchor" href="#pronunciation-principles" aria-label="Permalink to &quot;Pronunciation Principles&quot;">​</a></h2><p>Pronunciation is taught explicitly. Never assume learners will acquire pronunciation naturally. Common pronunciation mistakes are always documented.</p><hr><h2 id="review-strategy" tabindex="-1">Review Strategy <a class="header-anchor" href="#review-strategy" aria-label="Permalink to &quot;Review Strategy&quot;">​</a></h2><ul><li>Every five lessons: a Review Lesson.</li><li>Every unit: an Assessment.</li><li>Every CEFR level: a Comprehensive Review.</li></ul><p>Reviews introduce no new grammar and no new vocabulary. <strong>See:</strong> <code>docs/REVIEW_STRATEGY.md</code>.</p><hr><h2 id="ai-generation-principles" tabindex="-1">AI Generation Principles <a class="header-anchor" href="#ai-generation-principles" aria-label="Permalink to &quot;AI Generation Principles&quot;">​</a></h2><p>AI must never invent curriculum, skip prerequisites, introduce future grammar or vocabulary, or duplicate explanations.</p><p>AI must always follow project standards, reference existing documents, maintain consistency, and prioritize clarity.</p><p><strong>See:</strong> <code>docs/AI_GUIDELINES.md</code> for the full workflow.</p><hr><h2 id="quality-standards" tabindex="-1">Quality Standards <a class="header-anchor" href="#quality-standards" aria-label="Permalink to &quot;Quality Standards&quot;">​</a></h2><p>Every lesson must pass quality review. Minimum requirements include grammar progression, vocabulary progression, reading validation, lesson template compliance, CSV generation, quiz generation, homework, review integration, grammar map update, and vocabulary database update.</p><p><strong>See:</strong> <code>docs/QUALITY_CHECKLIST.md</code>.</p><hr><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><p>A successful graduate of this curriculum should be able to:</p><ul><li>Hold everyday conversations.</li><li>Understand common spoken Dutch.</li><li>Read newspapers with assistance.</li><li>Write emails and messages.</li><li>Interact confidently in Dutch society.</li><li>Pass a B1 Dutch examination.</li></ul><hr><h2 id="guiding-principle" tabindex="-1">Guiding Principle <a class="header-anchor" href="#guiding-principle" aria-label="Permalink to &quot;Guiding Principle&quot;">​</a></h2><p>Every decision should answer one question:</p><p><strong>&quot;Will this make the learner more confident using Dutch in real life?&quot;</strong></p><p>If the answer is no, reconsider the decision.</p><hr><h2 id="relationship-to-other-documents" tabindex="-1">Relationship to Other Documents <a class="header-anchor" href="#relationship-to-other-documents" aria-label="Permalink to &quot;Relationship to Other Documents&quot;">​</a></h2><p>This document states <em>why</em> and <em>what</em> at the highest level. It intentionally does not repeat detail that already has a single authoritative home elsewhere:</p><table tabindex="0"><thead><tr><th>Question</th><th>Authoritative Document</th></tr></thead><tbody><tr><td>Why do we teach this way? (rationale, worked examples)</td><td><code>docs/TEACHING_PHILOSOPHY.md</code></td></tr><tr><td>What exactly belongs in each CEFR level?</td><td><code>docs/CEFR_GUIDE.md</code></td></tr><tr><td>What competencies make up each level?</td><td><code>docs/COMPETENCY_MAP.md</code></td></tr><tr><td>What lessons/units exist and how do they depend on each other?</td><td><code>docs/CURRICULUM.md</code></td></tr><tr><td>What is the exact lesson template?</td><td><code>docs/LESSON_STANDARD.md</code></td></tr><tr><td>What grammar exists and when is it taught?</td><td><code>docs/GRAMMAR_MAP.md</code>, <code>shared/grammar/</code></td></tr><tr><td>What vocabulary exists and when is it taught?</td><td><code>docs/VOCABULARY_ROADMAP.md</code>, <code>shared/vocabulary/master.csv</code></td></tr><tr><td>How are review lessons built?</td><td><code>docs/REVIEW_STRATEGY.md</code></td></tr><tr><td>How should content be formatted?</td><td><code>docs/STYLE_GUIDE.md</code></td></tr><tr><td>How should AI agents behave?</td><td><code>docs/AI_GUIDELINES.md</code></td></tr><tr><td>How is a lesson validated?</td><td><code>docs/QUALITY_CHECKLIST.md</code></td></tr><tr><td>What are the repository&#39;s engineering conventions?</td><td><code>PROJECT.md</code></td></tr></tbody></table><p>If any of those documents ever conflicts with the principles stated here, this document takes precedence and the conflicting document must be corrected.</p>`,104)])])}const m=i(t,[["render",o]]);export{h as __pageData,m as default};
